/** Path-effect composition and geometry fallbacks.
 * Standalone native effects stay native; trim uses Skia's native path trimmer.
 * Native extension factories/filterPath are preferred when present. Corner geometry
 * preserves quadratic, conic and cubic verbs; fallback discrete/morph remain approximate.
 */
export function createPathEffectExtensions(K,api){
  const {SKPathEffect,SKPath,SKPathMeasure,SKMatrix,SKPoint}=api;
  const native=()=>K.SkiaSharpNative?.Effects;
  const val=x=>x?.value??x,arr=x=>x?.ToArray?.()??x?.Values??x;
  const clone=effect=>effect?._clone?.()??(effect?effect.constructor._fromNative(effect._native.clone()):null);
  function cloneRecipe(r){const result={...r};if(r.path)result.path=r.path.Clone();if(r.matrix)result.matrix=Array.from(r.matrix);if(r.intervals)result.intervals=r.intervals.slice();return result;}
  function attach(effect,recipe){if(!effect)return effect;effect._geometry=cloneRecipe(recipe);effect._clone=function(){this.ThrowIfDisposed();return attach(this.constructor._fromNative(this._native.clone()),this._geometry);};const base=effect.Dispose;effect.Dispose=function(){if(this.IsDisposed)return;this._geometry?.path?.Dispose();base.call(this);};return effect;}
  class SoftwarePathEffect extends SKPathEffect {
    constructor(kind,options={},children=[]){super();this._software=true;this.Kind=kind;this._options={...options};this._children=children.map(clone);}
    _clone(){this.ThrowIfDisposed();return new SoftwarePathEffect(this.Kind,this._options,this._children);}
    FilterPath(path,paint=null){return applyPathEffect(path,this,paint);}
    Dispose(){if(this.IsDisposed)return;this._children.forEach(x=>x?.Dispose());this._children=[];super.Dispose();}
  }
  const original=Object.fromEntries(Object.getOwnPropertyNames(SKPathEffect).filter(n=>n.startsWith('Create')).map(n=>[n,SKPathEffect[n]]));
  SKPathEffect.CreateDash=(intervals,phase=0)=>attach(original.CreateDash.call(SKPathEffect,intervals,phase),{kind:'dash',intervals:Array.from(intervals),phase});
  SKPathEffect.CreateCorner=radius=>attach(original.CreateCorner.call(SKPathEffect,radius),{kind:'corner',radius});
  SKPathEffect.CreateDiscrete=(length,deviation,seed=0)=>attach(original.CreateDiscrete.call(SKPathEffect,length,deviation,seed),{kind:'discrete',length,deviation,seed});
  SKPathEffect.Create1DPath=(path,advance,phase=0,style=K.Path1DEffect.Translate)=>attach(original.Create1DPath.call(SKPathEffect,path,advance,phase,(typeof style==='number'?K.Path1DEffect.values[style]:style)),{kind:'path1d',path,advance,phase,style:val(style)});
  SKPathEffect.Create2DPath=(matrix,path)=>attach(original.Create2DPath.call(SKPathEffect,matrix,path),{kind:'path2d',path,matrix:arr(matrix)});
  SKPathEffect.Create2DLine=(width,matrix)=>attach(original.Create2DLine.call(SKPathEffect,width,matrix),{kind:'line2d',width,matrix:arr(matrix)});
  const SKTrimPathEffectMode=Object.freeze({Normal:0,Inverted:1});
  SKPathEffect.CreateTrim=(start,stop,mode=0)=>{if(!Number.isFinite(start)||!Number.isFinite(stop)||![0,1].includes(val(mode)))throw new RangeError('Trim needs finite fractions and a valid mode.');if(native()?.MakeTrimPathEffect)return SKPathEffect._fromNative(native().MakeTrimPathEffect(start,stop,val(mode)));return new SoftwarePathEffect('trim',{start:Math.max(0,Math.min(1,start)),stop:Math.max(0,Math.min(1,stop)),invert:val(mode)===1});};
  SKPathEffect.CreateCompose=(outer,inner)=>{if(!outer||!inner)throw new TypeError('Compose requires two path effects.');if(!outer._software&&!inner._software&&native()?.MakeComposePathEffect)return SKPathEffect._fromNative(native().MakeComposePathEffect(outer._native,inner._native));return new SoftwarePathEffect('compose',{},[outer,inner]);};
  SKPathEffect.CreateSum=(first,second)=>{if(!first||!second)throw new TypeError('Sum requires two path effects.');if(!first._software&&!second._software&&native()?.MakeSumPathEffect)return SKPathEffect._fromNative(native().MakeSumPathEffect(first._native,second._native));return new SoftwarePathEffect('sum',{},[first,second]);};
  function withMeasure(path,fn){const m=new SKPathMeasure(path,false,2),out=new SKPath();try{do{if(m.Length>0)fn(m,out);}while(m.NextContour());return out;}catch(e){out.Dispose();throw e;}finally{m.Dispose();}}
  function dash(path,r){const total=r.intervals.reduce((a,b)=>a+b,0);return withMeasure(path,(m,out)=>{let phase=((r.phase%total)+total)%total,index=0;while(phase>=r.intervals[index]&&index<r.intervals.length){phase-=r.intervals[index++];}index%=r.intervals.length;let distance=0,remainder=r.intervals[index]-phase,guard=0;while(distance<m.Length){if(remainder<=0){index=(index+1)%r.intervals.length;remainder=r.intervals[index];if(++guard>r.intervals.length)throw new Error('Invalid all-zero dash intervals.');continue;}guard=0;const stop=Math.min(m.Length,distance+remainder);if(index%2===0)m.GetSegment(distance,stop,out,true);distance=stop;index=(index+1)%r.intervals.length;remainder=r.intervals[index];}});}
  function sampled(m,step){const count=Math.max(1,Math.ceil(m.Length/step)),pts=Array.from({length:count+(m.IsClosed?0:1)},(_,i)=>m.GetPosition(i*m.Length/count));return {pts,closed:m.IsClosed};}
  function corner(path,r){
    if(!(r.radius>0))return path.Clone();const out=new SKPath(),commands=Array.from(path._native.toCmds()),sizes=[2,2,4,5,6,0],contours=[];let contour;
    for(let i=0;i<commands.length;){const verb=commands[i++],values=commands.slice(i,i+sizes[verb]);i+=sizes[verb];if(verb===0){contour={closed:false,records:[]};contours.push(contour);}if(!contour)continue;contour.records.push({verb,values});if(verb===5)contour.closed=true;}
    // SkCornerPathEffect rounds only linear corners. Bezier segments are copied
    // unchanged; sampling a curve here changes its topology and radius semantics.
    let previous=-1,valid=true,step=[0,0],firstStep=[0,0],move=[0,0],last=[0,0],current=[0,0];
    const emit=(verb,v,closed)=>{if(verb===0){if(previous===1)out.LineTo(...last);current=v.slice();if(closed){move=v.slice();valid=false;}else{out.MoveTo(...v);valid=true;}}
      else if(verb===1){const dx=v[0]-current[0],dy=v[1]-current[1],distance=Math.hypot(dx,dy),factor=distance<=2*r.radius?.5:r.radius/distance;step=[dx*factor,dy*factor];if(!valid){out.MoveTo(move[0]+step[0],move[1]+step[1]);valid=true;}else out.QuadTo(current[0],current[1],current[0]+step[0],current[1]+step[1]);if(distance>2*r.radius)out.LineTo(v[0]-step[0],v[1]-step[1]);last=v.slice();current=v.slice();}
      else if(verb>=2&&verb<=4){if(!valid){out.MoveTo(...current);valid=true;}if(verb===2)out.QuadTo(...v);else if(verb===3)out.ConicTo(...v);else out.CubicTo(...v);last=verb===3?v.slice(2,4):v.slice(-2);current=last.slice();firstStep=[0,0];}
      else if(verb===5){if(firstStep[0]||firstStep[1])out.QuadTo(last[0],last[1],last[0]+firstStep[0],last[1]+firstStep[1]);out.Close();valid=false;current=move.slice();}if(previous===0)firstStep=step.slice();previous=verb;};
    try{for(const c of contours){for(const {verb,values} of c.records){if(verb===5&&(current[0]!==move[0]||current[1]!==move[1]))emit(1,move,c.closed);emit(verb,values,c.closed);}}if(valid)out.LineTo(...last);out.FillType=path.FillType;return out;}catch(error){out.Dispose();throw error;}
  }
  function discrete(path,r){if(!(r.length>0))throw new RangeError('Discrete segment length must be positive.');let state=(r.seed>>>0)||0x9e3779b9;const random=()=>{state^=state<<13;state^=state>>>17;state^=state<<5;return (state>>>0)/4294967296;};return withMeasure(path,(m,out)=>{const {pts,closed}=sampled(m,r.length);for(const p of pts){p.X+=(random()*2-1)*r.deviation;p.Y+=(random()*2-1)*r.deviation;}out.AddPoly(pts,closed);});}
  function path1d(path,r){if(!(r.advance>0))throw new RangeError('Path advance must be positive.');return withMeasure(path,(m,out)=>{for(let d=((r.phase%r.advance)+r.advance)%r.advance;d<m.Length;d+=r.advance){const pos=m.GetPositionAndTangent(d);if(!pos)continue;if(r.style===2){const stamp=r.path.Clone();try{const commands=Array.from(stamp._native.toCmds()),lengths=[2,2,4,5,6,0];for(let i=0;i<commands.length;){const verb=commands[i++],count=lengths[verb];for(let j=0;j<count-(verb===3?1:0);j+=2){const x=commands[i+j],y=commands[i+j+1],v=m.GetPositionAndTangent(Math.max(0,Math.min(m.Length,d+x)));if(v){commands[i+j]=v.Position.X-v.Tangent.Y*y;commands[i+j+1]=v.Position.Y+v.Tangent.X*y;}}i+=count;}const native=K.Path.MakeFromCmds(commands),p=SKPath._fromNative(native);try{out.AddPath(p);}finally{p.Dispose();}}finally{stamp.Dispose();}}
        else{const [x,y]=[pos.Position.X,pos.Position.Y],tx=r.style===1?pos.Tangent.X:1,ty=r.style===1?pos.Tangent.Y:0;out.AddPath(r.path,new SKMatrix(tx,-ty,x,ty,tx,y,0,0,1));}}});}
  function path2d(path,r){const matrix=new SKMatrix(r.matrix),inverse=matrix.TryInvert();if(!inverse.Success)throw new RangeError('2D path-effect matrix must be invertible.');const local=path.Clone(),out=new SKPath();try{local.Transform(inverse.Inverse);const b=local.Bounds,left=Math.floor(b.Left)-1,right=Math.ceil(b.Right)+1,top=Math.floor(b.Top)-1,bottom=Math.ceil(b.Bottom)+1;if((right-left)*(bottom-top)>1000000)throw new RangeError('2D path effect exceeds one million lattice cells.');for(let y=top;y<bottom;y++){if(r.kind==='line2d'){const strip=new SKPath();try{strip.AddRect(new api.SKRect(left,y-r.width/2,right,y+r.width/2));strip.Op(local,api.SKPathOp.Intersect,strip);strip.Transform(matrix);out.AddPath(strip);}finally{strip.Dispose();}}else for(let x=left;x<right;x++)if(local.Contains(x+.5,y+.5)){const center=matrix.MapPoint(x+.5,y+.5);out.AddPath(r.path,SKMatrix.CreateTranslation(center.X,center.Y));}}return out;}catch(e){out.Dispose();throw e;}finally{local.Dispose();}}
  function applyPathEffect(path,effect,paint=null){path.ThrowIfDisposed();if(!effect)return path.Clone();effect.ThrowIfDisposed();if(effect._software){const [a,b]=effect._children,o=effect._options;if(effect.Kind==='trim'){const p=path._native.makeTrimmed(o.start,o.stop,o.invert);return p?SKPath._fromNative(p):new SKPath();}if(effect.Kind==='compose'){const inner=applyPathEffect(path,b,paint);try{return applyPathEffect(inner,a,paint);}finally{inner.Dispose();}}if(effect.Kind==='sum'){const first=applyPathEffect(path,a,paint),second=applyPathEffect(path,b,paint);try{first.AddPath(second);return first;}catch(e){first.Dispose();throw e;}finally{second.Dispose();}}throw new Error('Unknown path effect node: '+effect.Kind);}
    if(native()?.FilterPath){let held=null;try{const p=paint?._native??(held=new K.Paint());if(held){held.setStyle(K.PaintStyle.Stroke);held.setStrokeWidth(0);}const result=native().FilterPath(effect._native,path._native,p,1,null);return result?SKPath._fromNative(result):path.Clone();}finally{held?.delete();}}
    const r=effect._geometry;if(!r)throw new api.SKNotSupportedError('Path geometry conversion requires an effect created by this API instance.');if(r.kind==='dash')return dash(path,r);if(r.kind==='corner')return corner(path,r);if(r.kind==='discrete')return discrete(path,r);if(r.kind==='path1d')return path1d(path,r);if(r.kind==='path2d'||r.kind==='line2d')return path2d(path,r);throw new Error('Unknown native path effect geometry: '+r.kind);
  }
  return {SoftwarePathEffect,SKTrimPathEffectMode,SKPath1DPathEffectStyle:K.Path1DEffect,applyPathEffect};
}
